from pathlib import Path
from html import escape
import json,shutil
R=Path(__file__).resolve().parent
assets=json.loads((R/'manifest.json').read_text())['assets'];records=json.loads((R/'generation-records.json').read_text())['assets']
desc={'A':'Sealed organic-waste bale, stopped conveyor, completed indicator and disposal receipt. Processing is finished.','B':'Fresh nursery mound, standby hopper, arms at rest and a cheerful sprout marker beneath the artificial sun.','C':'An anonymous person-sized mass made entirely of roots, leaves and flowers; the cultivation lamp reports success.','D':'Level growing tray, formal checkmark, closed waste hatch and retracted handling arms in an enclosed processing station.','E':'Roots completely obstruct the narrow service duct while the overhead translator issues another routine requisition.'}
def fig(stem,title):
 return f'<figure><div class="scroll"><img class="pixel scaled" data-stem="{stem}" src="previews/{stem}-native.png" alt="{escape(title)}"></div><figcaption>{escape(title)}</figcaption></figure>'
html='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Biology Park · Batch8 · Five aftermaths</title><link rel="stylesheet" href="gallery.css"></head><body><header><div class="eyebrow">The Acceptable Error / Chapter2 / Batch8 / November17,2026</div><h1>Five bureaucratic<br>aftermaths.</h1><p class="status">Five generated candidates · Art Director selection pending</p><p>Batch7 is complete and approved. All109 selected public-art hashes match their registered sources. These five new death illustrations remain generated and unselected, with null production paths.</p><nav><a href="#items">Five candidates</a><a href="#groups">Approved-art comparisons</a><a href="#popup">Existing popup composition</a><a href="#evidence">QA and provenance</a></nav></header><div class="toolbar"><div class="toolbar-inner"><div class="button-group"><button data-scale="1" aria-pressed="true">Native314×206</button><button data-scale="2" aria-pressed="false">Popup2×</button><button data-scale="4" aria-pressed="false">Inspect4×</button></div><span class="muted">Exact integer PNGs · nearest-neighbor · full-size views scroll</span></div></div><main><section id="items"><h2>Five independent aftermath illustrations</h2><p>Native314×206 opaque RGB, popup628×412 exact2×, inspection1256×824 exact4×. Existing64-color palette, no dithering. Titles, subtitles, prose, separators, controls and the frozen gameplay backdrop remain separate from the image.</p>'''
for a in assets:
 k=a['id'];stem=Path(a['candidatePath']).stem
 html+=f'<article class="asset" id="asset-{k}" data-width="314" data-height="206"><header><div class="eyebrow">{k} / RGB314×206 / generated, unselected</div><h3>{escape(a["title"])}</h3><code>{a["registryKey"]}</code><p>{desc[k]}</p></header>'+fig(stem,a['title'])+f'<div class="asset-links"><a href="{a["candidatePath"]}">Native PNG</a><a href="{a["popupPreview"]}">Exact2× popup PNG</a><a href="{a["inspectionPreview"]}">Exact4× inspection</a><a href="{a["sourcePath"]}">Original full-resolution generation</a><a href="{records[k]["prompt"]}">Exact prompt</a></div></article>'
html+='</section><section id="groups"><h2>Continuity and distinct consequences</h2>'+fig('five-aftermaths','All five aftermaths at native logical resolution')
for a in assets:html+=fig(a['id']+'-approved-scene-comparison','Approved related scene → '+a['title'])
html+=fig('B-D-distinct-aftermaths','Nursery welcome mound versus industrial reclassification tray')
html+='</section><section id="popup"><h2>Existing A1 popup composition</h2><p>Rendered with the unchanged pinned game popup renderer, configuration and bitmap fonts. Each candidate occupies the exact628×412 art area. Canonical title, subtitle and narrative remain separate. The backdrop uses the related approved scene as a frozen review stand-in with the existing10px block/0.35 darkening effect. These are art-review compositions; candidate bindings do not select or integrate artwork.</p>'
for a in assets:
 k=a['id'];p=f'popup-previews/{k}-popup-1920x1080.png';html+=f'<figure class="popup"><div class="scroll"><img class="pixel popup-image" src="{p}" alt="{escape(a["title"])} in the existing A1 popup"></div><figcaption>{escape(a["title"])} · <a href="{p}">Full1920×1080 composition PNG</a></figcaption></figure>'
html+='</section><section id="evidence"><h2>Evidence and handoff</h2><div class="docs">'
docs={'README.md':'Batch8 handoff','BATCH7_APPROVAL.md':'Final Batch7 approval;109 hashes','CANDIDATE_HASHES.md':'Five candidate paths and SHA-256','ARTWORK_CONTINUITY_REVIEW.md':'Visual findings','STORY_CONTINUITY.md':'Fatal routes and shared outcomes','qa.json':'Native, opacity, palette and scaling QA','popup-review-qa.json':'Actual existing-renderer proof','popup-ui-provenance.json':'Pinned UI provenance','gallery-verification.json':'Browser gallery QA','manifest.json':'Candidate manifest','generation-records.json':'Original generations and prompts','PNG_SHA256SUMS.txt':'PNG checksums','SOURCE_SHA256SUMS.txt':'Original source checksums','REMAINING_QUEUE.md':'No Chapter2 artwork not-started','PUBLICATION.md':'Generated-status publication'}
for p,t in docs.items():html+=f'<a class="doc" href="{p}"><strong>{t}</strong><span>{p}</span></a>'
html+='''</div><p>Original source generations, exact prompts and approved-reference provenance are preserved. All prior artwork is unchanged. Technical QA does not constitute owner approval. No gameplay integration, death-copy changes or new death mechanics.</p></section></main><footer>Five generated death illustrations · stop for Art Director review</footer><script>'use strict';function setScale(s){document.querySelectorAll('[data-scale]').forEach(b=>b.setAttribute('aria-pressed',String(Number(b.dataset.scale)===s)));document.querySelectorAll('.scaled').forEach(i=>i.src='previews/'+i.dataset.stem+(s===1?'-native.png':'-'+s+'x.png'));}document.querySelectorAll('[data-scale]').forEach(b=>b.addEventListener('click',()=>setScale(Number(b.dataset.scale))));</script></body></html>'''
(R/'index.html').write_text(html)
shutil.copy2(R.parent/'chapter-02-batch07-2026-11-17/gallery.css',R/'gallery.css')
print('Five cards,7 reference/consequence boards,5 actual popup compositions,1x/2x/4x controls.')
